// Pilihan 1: tulis fungsi berbeda untuk tiap tipe — duplikasi!
function ambilPertamaString(arr: string[]): string {
  return arr[0];
}
function ambilPertamaNumber(arr: number[]): number {
  return arr[0];
}
function ambilPertamaBoolean(arr: boolean[]): boolean {
  return arr[0];
}
// Dan seterusnya... 🥱

// Pilihan 2: pakai any — kehilangan type safety
function ambilPertama(arr: any[]): any {
  return arr[0];
}
const hasil = ambilPertama(['apel', 'mangga']);
hasil.toFixed(2); // TS tidak protes, padahal 'apel' bukan number! 💥

// <T> adalah 'type parameter' — placeholder untuk tipe apapun
function ambilPertama<T>(arr: T[]): T {
  return arr[0];
}

// TypeScript infer T dari argumen yang diberikan:
const buah = ambilPertama(['apel', 'mangga', 'jeruk']);
// T = string, buah bertipe: string

const angka = ambilPertama([1, 2, 3, 4, 5]);
// T = number, angka bertipe: number

const flags = ambilPertama([true, false, true]);
// T = boolean, flags bertipe: boolean

// TypeScript sekarang TAHU tipenya:
buah.toUpperCase(); // ✅ string method tersedia
angka.toFixed(2);   // ✅ number method tersedia
buah.toFixed(2);    // ❌ Error: 'toFixed' tidak ada di string

// Dua type parameter: T dan U
function pasangkan<T, U>(pertama: T, kedua: U): [T, U] {
  return [pertama, kedua];
}

const pasangan1 = pasangkan('nama', 25);
// tipe: [string, number]

const pasangan2 = pasangkan(true, ['a', 'b', 'c']);
// tipe: [boolean, string[]]

// Generic transform
function transformasi<TInput, TOutput>(
  data: TInput,
  transformer: (input: TInput) => TOutput
): TOutput {
  return transformer(data);
}

const panjangTeks = transformasi('halo dunia', str => str.length);
// TInput = string, TOutput = number
// panjangTeks bertipe: number

// Fungsi generic yang berguna untuk data fetching
async function ambilData<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`HTTP error: ${response.status}`);
  }
  return response.json() as T;
}

// Penggunaan — spesifikasikan tipe yang diharapkan:
interface Produk { id: number; nama: string; harga: number; }
interface User { id: number; nama: string; email: string; }

const produk = await ambilData<Produk>('/api/produk/1');
// produk bertipe: Produk — TS tahu semua property-nya!

const user = await ambilData<User>('/api/user/1');
// user bertipe: User

// Generic class/interface untuk response API
interface ApiResponse<T> {
  data: T;
  status: number;
  pesan: string;
  berhasil: boolean;
}

// Pakai dengan tipe berbeda
type ResponseProduk = ApiResponse<Produk>;
type ResponseListUser = ApiResponse<User[]>;
type ResponseLogin = ApiResponse<{ token: string; user: User }>;

// Fungsi yang return ApiResponse
async function fetchApi<T>(url: string): Promise<ApiResponse<T>> {
  const response = await fetch(url);
  return response.json();
}

const result = await fetchApi<Produk[]>('/api/produk');
// result.data bertipe: Produk[] ✅
// result.status bertipe: number ✅
// result.data[0].nama bertipe: string ✅

// Tanpa constraint — T bisa apa saja
function tampilkanPanjang<T>(item: T) {
  console.log(item.length); // ❌ Error: T mungkin tidak punya .length
}

// Dengan constraint — T harus punya property 'length'
interface PunyaPanjang {
  length: number;
}

function tampilkanPanjang<T extends PunyaPanjang>(item: T) {
  console.log(item.length); // ✅ Aman — T pasti punya .length
}

tampilkanPanjang('halo');        // ✅ string punya .length
tampilkanPanjang([1, 2, 3]);     // ✅ array punya .length
tampilkanPanjang({ length: 5 }); // ✅ objek dengan property length
tampilkanPanjang(42);            // ❌ Error: number tidak punya .length

// keyof T = union dari semua nama property T
// K extends keyof T = K harus nama property yang ada di T
function ambilNilai<T, K extends keyof T>(objek: T, kunci: K): T[K] {
  return objek[kunci];
}

const user = { nama: 'Budi', umur: 25, email: 'budi@mail.com' };

const namanya = ambilNilai(user, 'nama');   // tipe: string ✅
const umurnya = ambilNilai(user, 'umur');   // tipe: number ✅
ambilNilai(user, 'telepon'); // ❌ Error: 'telepon' bukan property User

// T harus bisa di-compare (punya method compareTo, atau setidaknya number/string)
function cariMaks<T extends number | string>(arr: T[]): T {
  return arr.reduce((maks, item) => item > maks ? item : maks);
}

cariMaks([3, 1, 4, 1, 5, 9]); // 9
cariMaks(['banana', 'apple', 'cherry']); // 'cherry'
cariMaks([true, false]); // ❌ boolean tidak memenuhi constraint

// Constraint berganda — T harus implements banyak interface
interface Serializable {
  serialize(): string;
}
interface Identifiable {
  id: number;
}

function simpanDanLog<T extends Serializable & Identifiable>(item: T) {
  console.log(`Simpan item #${item.id}`);
  database.simpan(item.serialize());
}

// Interface generic untuk stack data structure
interface Stack<T> {
  push(item: T): void;
  pop(): T | undefined;
  peek(): T | undefined;
  ukuran(): number;
  kosong(): boolean;
}

// Implementasi
class StackArray<T> implements Stack<T> {
  private items: T[] = [];

  push(item: T) { this.items.push(item); }
  pop(): T | undefined { return this.items.pop(); }
  peek(): T | undefined { return this.items[this.items.length - 1]; }
  ukuran() { return this.items.length; }
  kosong() { return this.items.length === 0; }
}

// Pakai dengan tipe berbeda
const stackAngka = new StackArray<number>();
stackAngka.push(1);
stackAngka.push(2);
const atas = stackAngka.peek(); // tipe: number | undefined

const stackTeks = new StackArray<string>();
stackTeks.push('halo');
stackTeks.push('world');
const teks = stackTeks.pop(); // tipe: string | undefined

// Dengan any — kehilangan type safety
function pertamaAny(arr: any[]): any {
  return arr[0];
}
const x = pertamaAny([1, 2, 3]);
x.toUpperCase(); // TS tidak protes! 💥 Runtime error menanti

// Dengan generics — type safe!
function pertamaGeneric<T>(arr: T[]): T {
  return arr[0];
}
const y = pertamaGeneric([1, 2, 3]);
y.toUpperCase(); // ❌ Error: 'toUpperCase' tidak ada di number
y.toFixed(2);    // ✅ Method number tersedia

// Dengan any — semua return type hilang:
const cache: Map<string, any> = new Map();
cache.set('user', { nama: 'Budi' });
const user = cache.get('user');
user.nama;        // tidak ada autocomplete, TS anggap any
user.tidakAda;    // TS tidak protes

// Dengan generics — type safe cache:
const cacheTyped = new Map<string, User>();
cacheTyped.set('user1', { id: 1, nama: 'Budi', email: '...' });
const userTyped = cacheTyped.get('user1'); // tipe: User | undefined
userTyped?.nama;      // ✅ autocomplete tersedia
userTyped?.tidakAda;  // ❌ Error: property tidak ada di User
